// About ClassifAI Studio (from the app menu or Settings), and the open source licenses of
// everything it ships (generated by scripts/licenses.py into src/licenses.json).
import { cn } from "@/lib/utils";
import { ChevronRight, ExternalLink, Scale } from "lucide-react";
import { useEffect, useMemo, useState } from "react";
import { Button, PageHeader, SearchField, Section, Spinner } from "../components/ui";
import { api, openExternal } from "../lib/api";
import { useApp, useAsync } from "../lib/app";

export const REPO_URL = "https://github.com/jonasweinert/classifai-studio";
const YEAR = 2026;

export function About() {
  const { go } = useApp();
  const info = useAsync(() => api.appInfo(), []);
  return (
    <div className="mx-auto max-w-[560px] pt-10 pb-12 fade-up">
      <img src="/logo.svg" alt="" className="size-20 drop-shadow-[0_6px_18px_rgba(0,0,0,.18)]" />
      <h1 className="mt-5 text-[28px] font-bold tracking-[-0.025em]">ClassifAI Studio</h1>
      <div className="mt-0.5 text-[13px] text-muted-foreground">Version {info.data?.version ?? "…"}</div>

      <div className="mt-6 space-y-3 text-[13.5px] leading-relaxed text-foreground/90">
        <p>ClassifAI Studio is an app for classifying and labelling text. You write questions, and models answer them for each entry, with a probability for each answer.</p>
        <p>
          It works with two kinds of models. Decision models are made for classification and take their probabilities from the model itself. LLMs answer the same questions, show the part of the text
          they used, can write free text, and estimate their own probabilities.
        </p>
        <p>You can compare models against labels you trust, and label entries yourself where you have none. Your data stays on this Mac unless you use a cloud model or LLM.</p>
      </div>

      <div className="mt-6 flex flex-wrap gap-2">
        <Button icon={<ExternalLink className="size-3.5" />} onClick={() => openExternal(REPO_URL)}>
          Source code on GitHub
        </Button>
        <Button variant="ghost" icon={<Scale className="size-3.5" />} onClick={() => go({ page: "licenses" })}>
          Open source licenses
        </Button>
      </div>

      <div className="mt-8 border-t border-border pt-4 text-[12px] leading-relaxed text-muted-foreground">
        <div>© {YEAR} Jonas Weinert. All rights reserved.</div>
        <button className="font-mono text-[11.5px] text-primary hover:underline" onClick={() => openExternal(REPO_URL)}>
          github.com/jonasweinert/classifai-studio
        </button>
        <div className="mt-2 text-faint">Built with Tauri, React, Rust and many other open source projects. Provider names and logos belong to their owners.</div>
      </div>
    </div>
  );
}

interface LicensePackage {
  name: string;
  version: string;
  license: string;
  url: string;
  text: number | null;
  source: "Rust" | "JavaScript" | "Assets";
  note?: string;
}

export function Licenses() {
  const { back } = useApp();
  const [data, setData] = useState<{ packages: LicensePackage[]; texts: string[] } | null>(null);
  const [query, setQuery] = useState("");
  const [open, setOpen] = useState<string | null>(null);
  // About 1.7 MB of license texts, loaded only when this page opens.
  useEffect(() => {
    import("../licenses.json").then((m) => setData(m.default as unknown as { packages: LicensePackage[]; texts: string[] }));
  }, []);

  const shown = useMemo(() => {
    const words = query.toLowerCase().split(/\s+/).filter(Boolean);
    return (data?.packages ?? []).filter((p) => words.every((w) => `${p.name} ${p.license} ${p.source}`.toLowerCase().includes(w)));
  }, [data, query]);
  const counts = useMemo(() => {
    const c: Record<string, number> = {};
    for (const p of data?.packages ?? []) c[p.license] = (c[p.license] ?? 0) + 1;
    return Object.entries(c).sort((a, b) => b[1] - a[1]);
  }, [data]);

  return (
    <>
      <PageHeader
        title="Open Source Licenses"
        subtitle={data ? `${data.packages.length} open source packages used in ClassifAI Studio` : "Loading…"}
        actions={
          <Button size="sm" variant="ghost" onClick={back}>
            Done
          </Button>
        }
      />
      {!data ? (
        <Spinner />
      ) : (
        <div className="max-w-[820px] fade-up">
          <p className="mb-4 text-[12.5px] leading-relaxed text-muted-foreground">
            Thanks to the people who make these projects. Click a package to see its license.
          </p>
          <div className="mb-4 flex flex-wrap gap-1.5">
            {counts.slice(0, 8).map(([l, n]) => (
              <button key={l} onClick={() => setQuery(query === l ? "" : l)} className={cn("rounded-full px-2.5 py-0.5 text-[11.5px] transition-colors", query === l ? "bg-primary text-primary-foreground" : "bg-sel text-muted-foreground hover:text-foreground")}>
                {l} · {n}
              </button>
            ))}
          </div>
          <SearchField className="mb-3 w-full" value={query} onChange={setQuery} placeholder="Search packages or licenses" />
          <Section title={`${shown.length} package${shown.length === 1 ? "" : "s"}`}>
            <div className="divide-y divide-border border-y border-border">
              {shown.map((p) => {
                const key = `${p.source}:${p.name}@${p.version}`;
                const isOpen = open === key;
                return (
                  <div key={key}>
                    <button onClick={() => setOpen(isOpen ? null : key)} className="flex w-full items-center gap-3 py-2 text-left hover:bg-sel/50">
                      <ChevronRight className={cn("size-3.5 shrink-0 text-faint transition-transform", isOpen && "rotate-90")} />
                      <span className="min-w-0 flex-1 truncate text-[13px]">
                        <span className="font-medium">{p.name}</span> <span className="font-mono text-[11.5px] text-faint">{p.version}</span>
                      </span>
                      <span className="shrink-0 text-[11px] text-faint">{p.source}</span>
                      <span className="w-[11rem] shrink-0 truncate text-right font-mono text-[11.5px] text-muted-foreground" title={p.license}>
                        {p.license}
                      </span>
                    </button>
                    {isOpen && (
                      <div className="mb-3 ml-6 fade-up">
                        <div className="mb-2 flex flex-wrap items-center gap-3 text-[12px]">
                          <button className="inline-flex items-center gap-1 text-primary hover:underline" onClick={() => openExternal(p.url)}>
                            {p.url.replace(/^https?:\/\//, "").replace(/^git\+/, "")} <ExternalLink className="size-3" />
                          </button>
                          {p.note && <span className="text-faint">{p.note}</span>}
                        </div>
                        {p.text !== null ? (
                          <pre className="max-h-[320px] overflow-auto rounded-[10px] bg-card p-3 font-mono text-[11px] leading-relaxed whitespace-pre-wrap text-muted-foreground" data-selectable>
                            {data.texts[p.text]}
                          </pre>
                        ) : (
                          <div className="text-[12px] text-muted-foreground">This package has no license file. It is licensed under {p.license}. See its repository for the terms.</div>
                        )}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </Section>
        </div>
      )}
    </>
  );
}
